<script setup>
import {computed,onMounted,ref} from 'vue'
import {useAuthStore} from '../stores/auth'
import {useMarketStore} from '../stores/market'
import {CATEGORIES} from '../data/seed'
import {action,date,money,notify} from '../lib/ui'
import Icon from '../components/Icon.vue'
const auth=useAuthStore(),market=useMarketStore(),tab=ref('overview'),users=ref([]),q=ref(''),status=ref(''),loading=ref(false),confirmation=ref(null)
const resetConfirmation=ref(null),resetBusy=ref(false)
const labels={available:'正在转让',reserved:'已被预订',sold:'已找到归宿',offline:'已下架'}
const products=computed(()=>market.products.filter(p=>(!q.value||`${p.title} ${p.sellerName} ${p.college}`.includes(q.value))&&(!status.value||p.status===status.value)))
const shownUsers=computed(()=>users.value.filter(u=>(!q.value||`${u.username} ${u.displayName} ${u.college}`.toLowerCase().includes(q.value.toLowerCase()))&&(!status.value||u.status===status.value)))
const completed=computed(()=>market.orders.filter(o=>o.status==='completed'))
const revenue=computed(()=>completed.value.reduce((sum,o)=>sum+o.amount,0))
async function load(){loading.value=true;try{users.value=await auth.fetchUsers()}catch(e){notify(e.message,'error')}finally{loading.value=false}}
onMounted(load)
function changeTab(value){tab.value=value;q.value='';status.value=''}
async function productStatus(product){await action(()=>market.setProductStatus(product.id,product.status==='available'?'offline':'available'),product.status==='available'?'商品已下架':'商品已恢复上架')}
function openReset(product){const orders=market.orders.filter(order=>['unpaid','paid'].includes(order.status)&&order.productIds.includes(product.id));resetConfirmation.value={productId:product.id,title:product.title,orderCount:orders.length,releasedCount:new Set([product.id,...orders.flatMap(order=>order.productIds)]).size}}
async function resetProduct(){resetBusy.value=true;try{const result=await market.resetProductForDemo(resetConfirmation.value.productId);notify(result.cancelledOrderCount?`已重置为在售，取消 ${result.cancelledOrderCount} 笔模拟订单并释放 ${result.releasedProductCount} 件商品`:'商品已重新上架，可再次演示购买；已完成订单历史保留');resetConfirmation.value=null}catch(e){notify(e.message,'error')}finally{resetBusy.value=false}}
async function toggleUser(){const u=confirmation.value;loading.value=true;try{const updated=await auth.setUserStatus(u.id,u.status==='active'?'disabled':'active');await market.setProfile(updated);await load();notify(updated.status==='active'?'账号已启用':'账号已停用，其登录会话已失效');confirmation.value=null}catch(e){notify(e.message,'error')}finally{loading.value=false}}
</script>
<template><div class="page-width inner-page admin-page"><div class="admin-heading"><div><span class="eyebrow">BEHIND THE LITTLE MARKET</span><h1>守护每一份校园相遇。</h1><p>让市集有序，让旧物安心奔赴下一站。</p></div><span class="admin-badge"><Icon name="shield" :size="17"/>市集管理员 · {{auth.user.displayName}}</span></div><div class="admin-tabs"><button v-for="item in [{id:'overview',label:'市集总览',icon:'grid'},{id:'products',label:'商品管理',icon:'box'},{id:'users',label:'用户管理',icon:'user'}]" :key="item.id" :class="{active:tab===item.id}" @click="changeTab(item.id)"><Icon :name="item.icon" :size="18"/>{{item.label}}</button><button class="text-link admin-refresh" @click="load"><Icon name="refresh" :size="16"/>刷新数据</button></div><div v-if="tab==='overview'"><div class="admin-stats"><div class="panel"><span><Icon name="box"/>校园闲置</span><strong>{{market.products.length}}<small>件</small></strong><p>{{market.products.filter(p=>p.status==='available').length}} 件等待新主人</p></div><div class="panel"><span><Icon name="user"/>相遇的同学</span><strong>{{users.filter(u=>u.role!=='admin').length}}<small>位</small></strong><p>四个学院，共同参与</p></div><div class="panel"><span><Icon name="leaf"/>已找到归宿</span><strong>{{market.products.filter(p=>p.status==='sold').length}}<small>件</small></strong><p>{{completed.length}} 笔校园交接已完成</p></div><div class="panel"><span><Icon name="heart"/>循环的价值</span><strong><small>¥</small>{{money(revenue)}}</strong><p>已完成订单的模拟金额</p></div></div><div class="admin-overview-grid"><section class="panel admin-chart"><div class="section-heading"><h2>好物分布</h2><span class="eyebrow">LITTLE THINGS, BIG STORIES</span></div><div v-for="category in CATEGORIES" :key="category.id" class="chart-row"><span>{{category.label}}</span><div><i :style="{width:`${market.products.filter(p=>p.category===category.id).length/Math.max(1,market.products.length)*100}%`}"></i></div><strong>{{market.products.filter(p=>p.category===category.id).length}}</strong></div></section><section class="panel admin-note"><Icon name="leaf" :size="43"/><span class="eyebrow">A KINDER WAY TO EXCHANGE</span><h2>好好使用，<br>就是最好的珍惜。</h2><p>关注真实描述，保持友善沟通。<br>一个有温度的市集，需要我们一起照顾。</p><button class="text-link" @click="changeTab('products')">去看看校园好物<Icon name="arrow" :size="17"/></button></section></div></div><section v-else class="panel admin-table-panel"><div class="admin-table-toolbar"><div><h2>{{tab==='products'?'校园商品':'校园用户'}}</h2><small>{{tab==='products'?products.length:shownUsers.length}} 条记录</small></div><div class="admin-table-controls"><div class="input-with-icon"><Icon name="search" :size="17"/><input v-model="q" :placeholder="tab==='products'?'搜索商品或卖家':'搜索用户名或昵称'" :aria-label="tab==='products'?'搜索管理商品':'搜索用户'"/></div><select v-model="status" aria-label="状态筛选"><option value="">全部状态</option><template v-if="tab==='products'"><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></template><template v-else><option value="active">已启用</option><option value="disabled">已停用</option></template></select></div></div><div class="table-scroll"><table v-if="tab==='products'"><thead><tr><th>商品信息</th><th>发布同学</th><th>转让价</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="product in products" :key="product.id"><td><RouterLink :to="`/product/${product.id}`" class="table-product"><img :src="product.images[0]" :alt="product.title"/><span>{{product.title}}<small>{{CATEGORIES.find(c=>c.id===product.category)?.label}}</small></span></RouterLink></td><td>{{product.sellerName}}<small class="table-subtext">{{product.college}}</small></td><td class="rose">¥{{money(product.price)}}</td><td><span :class="['tag',product.status]">{{labels[product.status]}}</span></td><td><button v-if="['available','offline'].includes(product.status)" class="button small-button outline" @click="productStatus(product)">{{product.status==='available'?'下架':'恢复上架'}}</button><button v-else-if="['reserved','sold'].includes(product.status)" class="button small-button outline" @click="openReset(product)">重置为在售（演示）</button><span v-else class="muted">暂不可操作</span></td></tr><tr v-if="!products.length"><td colspan="5" class="table-empty">没有符合条件的商品</td></tr></tbody></table><table v-else><thead><tr><th>校园用户</th><th>所在学院</th><th>角色</th><th>状态</th><th>注册时间</th><th>操作</th></tr></thead><tbody><tr v-for="user in shownUsers" :key="user.id"><td><div class="table-user"><span class="avatar small">{{user.displayName.slice(-2)}}</span><span>{{user.displayName}}<small>{{user.username}}</small></span></div></td><td>{{user.college||'—'}}</td><td>{{user.role==='admin'?'管理员':'学生'}}</td><td><span :class="['tag',user.status==='active'?'available':'offline']">{{user.status==='active'?'已启用':'已停用'}}</span></td><td>{{date(user.createdAt)}}</td><td><span v-if="user.role==='admin'" class="muted">受保护账号</span><button v-else class="button small-button outline" :disabled="loading" @click="confirmation=user">{{user.status==='active'?'停用':'启用'}}</button></td></tr><tr v-if="!shownUsers.length"><td colspan="6" class="table-empty">{{loading?'正在读取用户…':'没有符合条件的用户'}}</td></tr></tbody></table></div></section><Teleport to="body"><div v-if="confirmation" class="modal-overlay" @click.self="!loading&&(confirmation=null)"><section class="modal confirmation-modal"><Icon name="shield" :size="34"/><h2>{{confirmation.status==='active'?'确定停用这个账号？':'恢复这位同学的账号？'}}</h2><p>{{confirmation.displayName}}（{{confirmation.username}}）<br>{{confirmation.status==='active'?'停用后账号无法登录，已有登录会话立即失效。':'启用后，同学可以重新登录并继续使用市集。'}}</p><div class="modal-buttons"><button class="button outline" :disabled="loading" @click="confirmation=null">取消</button><button class="button primary" :disabled="loading" @click="toggleUser">{{loading?'处理中…':'确认'+(confirmation.status==='active'?'停用':'启用')}}</button></div></section></div><div v-if="resetConfirmation" class="modal-overlay" @click.self="!resetBusy&&(resetConfirmation=null)"><section class="modal confirmation-modal" role="dialog" aria-modal="true" aria-label="重置商品演示状态"><Icon name="refresh" :size="34"/><h2>重置这件商品为在售？</h2><p>“{{resetConfirmation.title}}”</p><p v-if="resetConfirmation.orderCount">将取消 {{resetConfirmation.orderCount}} 笔关联的未完成模拟订单，并释放整笔订单中的 {{resetConfirmation.releasedCount}} 件商品。这些商品都会重新开放购买。</p><p v-else>这件商品将重新出现在市集中，可再次演示购买。</p><p>已完成订单的历史记录会保留。</p><div class="modal-buttons"><button class="button outline" :disabled="resetBusy" @click="resetConfirmation=null">取消</button><button class="button primary" :disabled="resetBusy" @click="resetProduct">{{resetBusy?'重置中…':'确认重置为在售'}}</button></div></section></div></Teleport></div></template>
